export function getContextualDraft(situationSlug, documentSlug) {
  return CONTEXTUAL_DRAFTS[String(situationSlug || '') + '|' + String(documentSlug || '')] || null;
}
export function getContextualTitle(situationSlug, documentSlug, fallback) {
  return getContextualDraft(situationSlug, documentSlug)?.title || fallback;
}
